import{_ as i,o as n,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Bilder","description":"Alles über das Styling von Entitätsbildern.","frontmatter":{"title":"Bilder","description":"Alles über das Styling von Entitätsbildern."},"headers":[],"relativePath":"projects/uix/using/images.md","filePath":"projects/uix/using/images.md","lastUpdated":1793006827000}'),a={name:"projects/uix/using/images.md"};function r(d,e,l,o,c,p){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="entitatsbilder-stylen" tabindex="-1">Entitätsbilder stylen <a class="header-anchor" href="#entitatsbilder-stylen" aria-label="Permalink to &quot;Entitätsbilder stylen&quot;">​</a></h1><p>UIX kann das Hintergrundbild von Entitäten ersetzen, das von folgenden Elementen angezeigt wird:</p><ul><li><code>ha-entity-marker</code> für Entity-Marker in Map-Karten</li><li><code>ha-tile-icon</code> für Icons in Tile-Karten</li><li><code>state-badge</code> für State-Badges</li><li><code>ha-user-badge</code> für Benutzer-Badges</li><li><code>ha-person-badge</code> für Personen-Badges</li><li><code>hui-entity-badge</code> für Entity-Badges</li><li><code>hui-map-overview</code> für Personen und Geräte in der Map-Dashboard-Übersicht</li></ul><p>::: note Entity-Badges Aktiviere beim Entity-Badge <strong>Entitätsbild anzeigen</strong> beziehungsweise <code>show_entity_picture: true</code> in YAML, damit das Bild-Styling greift. :::</p><p>Das Styling kann über einen <a href="#override-fur-eine-entitat">Override für eine Entität</a> oder über einen <a href="#generischer-override">generischen Override</a> erfolgen.</p><h2 id="override-fur-eine-entitat" tabindex="-1">Override für eine Entität <a class="header-anchor" href="#override-fur-eine-entitat" aria-label="Permalink to &quot;Override für eine Entität&quot;">​</a></h2><p>Definiere eine CSS-Variable in der Form <code>--uix-image-for-&lt;entity_id&gt;</code>. Dabei wird jeder Punkt <code>.</code> in der Entity-ID durch <code>_</code> ersetzt. Wenn ein Element für die passende Entität gerendert wird, ersetzt UIX das Hintergrundbild durch die angegebene URL.</p><p>Templates werden unterstützt.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tile</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">entity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">person.jim</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    :host {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      --uix-image-for-person_jim: /local/photos/jim.jpg;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Die Variable kann auf jeder übergeordneten Ebene im DOM gesetzt werden. UIX erkennt sie über berechnete Styles am Element. Wenn die Variable nicht gesetzt ist oder die Entität nicht passt, bleibt das ursprüngliche Bild unverändert.</li><li>Für einen Override im gesamten Home-Assistant-Frontend setze <code>--uix-image-for-&lt;entity_id&gt;</code> in den Theme-Variablen <code>uix-root(-yaml)</code>, <code>uix-config(-yaml)</code> und <code>uix-more-info(-yaml)</code>.</li></ul></div><p>Die Bilder in der Map-Dashboard-Übersicht unterstützen ausschließlich Entity-spezifische Overrides. <code>--uix-image</code> gilt dort nicht.</p><h2 id="generischer-override" tabindex="-1">Generischer Override <a class="header-anchor" href="#generischer-override" aria-label="Permalink to &quot;Generischer Override&quot;">​</a></h2><p>Definiere die generische CSS-Variable <code>--uix-image</code> im Kontext des Bildes, das überschrieben werden soll. Das kann zum Beispiel ein Element sein, das <code>ha-entity-marker</code> in einer Map-Karte, <code>ha-tile-icon</code> in einer Tile-Karte oder <code>state-badge</code> in einer Entities-Zeile enthält.</p><p>Wenn ein unterstütztes Element in diesem Kontext gerendert wird, ersetzt UIX das Hintergrundbild durch die angegebene URL, unabhängig von der Entity-ID.</p><p>Templates werden unterstützt.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Wenn sowohl <code>--uix-image</code> als auch <code>--uix-image-for-&lt;entity_id&gt;</code> definiert sind, hat <code>--uix-image</code> Vorrang.</p></div>`,16)])])}const u=i(a,[["render",r]]);export{g as __pageData,u as default};
